<?php
namespace App\Services\Promotion;
use App\Models\Coupon; use App\Models\User; use Illuminate\Validation\ValidationException;
class CouponService { public function validate(string $code, float $subtotal, ?User $user=null): array { $c=Coupon::where('code',strtoupper(trim($code)))->firstOrFail(); if(!$c->is_active||($c->starts_at&&$c->starts_at->isFuture())||($c->ends_at&&$c->ends_at->isPast())||($c->usage_limit!==null&&$c->usage_count>=$c->usage_limit)||$subtotal<$c->minimum_purchase) throw ValidationException::withMessages(['coupon'=>['Voucher tidak dapat digunakan.']]); if($user&&$c->per_user_limit!==null&&$c->usages()->where('user_id',$user->id)->count()>=$c->per_user_limit) throw ValidationException::withMessages(['coupon'=>['Batas penggunaan voucher telah tercapai.']]); $d=$c->discount_type==='percentage'?$subtotal*((float)$c->discount_value/100):(float)$c->discount_value; return ['coupon'=>$c,'discount'=>min($d,(float)($c->maximum_discount??$d),$subtotal)]; } }
